const [x1, y1, x2, y2, x, y] = input;

const dx = x2 - x1;
const dy = y2 - y1;

// If parity of dx or dy doesn't match x,y parity, impossible
if ((Math.abs(dx) % 2) !== (x % 2) || (Math.abs(dy) % 2) !== (y % 2)) {
    console.log("NO");
    process.exit(0);
}

// Solve:
// dx = x*(a - b) + y*(c - d)
// dy = y*(a + b) + x*(c + d)
// Let p = a - b, q = c - d, r = a + b, s = c + d
// Then:
// dx = x*p + y*q
// dy = y*r + x*s
// Also a,b = (r ± p)/2, c,d = (s ± q)/2 must be integers >=0
// So r ≡ p (mod 2), s ≡ q (mod 2)

let possible = false;

// Try all parity combinations for p,q,r,s
for (let rp = 0; rp < 2 && !possible; rp++) {      // r ≡ p (mod 2)
    for (let sq = 0; sq < 2 && !possible; sq++) {  // s ≡ q (mod 2)
        // We only care about parity, so set:
        // p parity = rp, r parity = rp
        // q parity = sq, s parity = sq
        // We need integer solutions; we can directly solve for p,q,r,s:

        // From dx = x*p + y*q, dy = y*r + x*s
        // Choose p,q from dx equation, then r,s from dy equation.

        // Since x,y up to 1e5, brute force over small parity space only.

        // Solve for p,q as integers:
        // We'll treat it as 2-variable Diophantine; but we can parametrize:
        // For each integer k, set p = (dx - y*k)/x, q = k.
        // We only need some p,q that give valid r,s later.

        // Limit k range to keep p within reasonable bounds
        const limit = 100000; // heuristic

        for (let k = -limit; k <= limit && !possible; k++) {
            const q = k;
            const numeratorP = dx - y * q;
            if (numeratorP % x !== 0) continue;
            const p = numeratorP / x;

            // Check parity constraints for p,q
            if ((p & 1) !== rp || (q & 1) !== sq) continue;

            // Now solve for r,s from dy = y*r + x*s
            // Similarly parametrize s = t, r = (dy - x*t)/y
            for (let t = -limit; t <= limit && !possible; t++) {
                const s = t;
                const numeratorR = dy - x * s;
                if (numeratorR % y !== 0) continue;
                const r = numeratorR / y;

                if ((r & 1) !== rp || (s & 1) !== sq) continue;

                // Recover a,b,c,d
                const a = (r + p) / 2;
                const b = (r - p) / 2;
                const c = (s + q) / 2;
                const d = (s - q) / 2;

                if (a >= 0 && b >= 0 && c >= 0 && d >= 0 &&
                    Number.isInteger(a) && Number.isInteger(b) &&
                    Number.isInteger(c) && Number.isInteger(d)) {
                    possible = true;
                }
            }
        }
    }
}

